# Compact builder for the remaining 83 high-hooking 2026 columns (Total 90 new + 15 catalog = 105 new docs)
def make_rich_spec(
    slug: str, cat: str, catName: str, badge: str, calcLink: str, calcName: str,
    title: str, desc: str, keywords: list[str],
    hook_title: str, core_rule: str, second_rule: str,
    table_title: str, headers: list[str], rows: list[list[str]],
    sim_person: str, sim_case: str, sim_result: str,
    trap1: tuple[str, str], trap2: tuple[str, str], trap3: tuple[str, str], trap4: tuple[str, str],
    faq1: tuple[str, str], faq2: tuple[str, str], faq3: tuple[str, str],
    editor_tip: str,
) -> tuple:
    hook_p1 = (
        f"2026년 최신 세법·복지·금융 고시 개편으로 인해 '{keywords[0]}' 기준을 정확히 아느냐 모르느냐에 따라 "
        f"내 통장에 찍히는 현금이 수십만 원에서 수천만 원까지 갈립니다. 주변에서 카더라 통신만 믿고 신청을 포기하거나 "
        f"기한을 넘겨 혜택을 날리는 분들이 너무나 많습니다."
    )
    hook_p2 = (
        f"복잡한 공문서 용어는 싹 걷어내고, 당장 내가 대상이 되는지 1분 만에 확인하는 핵심 기준과 "
        f"구간별 실수령 금액 비교표, 그리고 현장에서 90%가 실수하는 4대 함정까지 명쾌하게 정리해 드립니다."
    )
    return (
        slug, cat, catName, badge, calcLink, calcName, title, desc, keywords,
        hook_title, hook_p1, hook_p2, editor_tip,
        f"1. {keywords[0]} 핵심 원리와 자격 요건, 이것만 기억하세요!", core_rule,
        f"2. 신청 전 반드시 챙겨야 할 2026년 우대 혜택과 실전 팁", second_rule,
        table_title, headers, rows,
        f"실전 계산: {sim_person}", f"• 상황 및 조건: {sim_case}\n• 최종 수령·절세 결과: {sim_result}",
        [trap1, trap2, trap3, trap4],
        [faq1, faq2, faq3],
    )

