# Compact blueprint converter for remaining 79 unique 2026 financial/welfare/business/real-estate columns
def bp_to_spec(bp: tuple) -> tuple:
    (
        slug, cat, catName, badge, calcLink, calcName,
        title, desc, kw1, kw2, kw3,
        hook_title, p1_a1, p1_a2,
        tbl_title, h1, h2, h3, r1, r2, r3,
        sim_person, sim_case, sim_res,
        t1_t, t1_b, t2_t, t2_b, t3_t, t3_b, t4_t, t4_b,
        q1, a1, q2, a2, q3, a3, tip
    ) = bp
    return make_rich_spec(
        slug, cat, catName, badge, calcLink, calcName,
        title, desc, [kw1, kw2, kw3],
        hook_title, p1_a1, p1_a2,
        tbl_title, [h1, h2, h3], [list(r1), list(r2), list(r3)],
        sim_person, sim_case, sim_res,
        (t1_t, t1_b), (t2_t, t2_b), (t3_t, t3_b), (t4_t, t4_b),
        (q1, a1), (q2, a2), (q3, a3), tip
    )

