        "Q. 올해 태어난 아기 병원비도 한도 없이 다 공제되나요?", "네, 만 6세 이하 영유아와 만 65세 이상 어르신, 본인을 위해 지출한 의료비는 연 700만 원 한도 제한 없이 전액 15% 공제됩니다.",
