     "대출을 실행할 때 은행 직원이 물어보는 '원리금균등분할상환으로 하실래요, 원금균등분할상환으로 하실래요?'라는 질문에 아무 생각 없이 대답하면 수천만 원이 왔다 갔다 합니다! 두 방식의 차이는 단 한 줄로 요약됩니다. 매달 내는 돈을 똑같이 맞출 것인가(원리금균등), 아니면 총이자를 가장 적게 내고 갈수록 편해질 것인가(원금균등)입니다.",
     "총이자 총액을 아끼려면 무조건 '원금균등분할상환'이 1등입니다(첫 달부터 원금을 많이 갚아나가므로 이자가 빠르게 줄어듦). 반대로 'DSR 대출 한도를 최대한 많이 뽑아야 하거나 초기 1~5년 월 상환 부담을 줄여야 할 때'는 첫해 상환액이 적은 원리금균등이나 체증식 상환(디딤돌·보금자리론 청년 전용)을 선택하는 것이 유리합니다.",
