     "그동안 대출받은 지 3년이 안 됐을 때 돈을 미리 갚거나 더 싼 은행으로 갈아타려 하면 1.2%~1.5%에 달하는 비싼 '중도상환수수료'가 발목을 잡았습니다. 하지만 금융위원회의 중도상환수수료 개편안 시행으로 은행이 실제 발생한 자금운용 실비용만 부과하도록 바뀌면서 시중은행 주담대 중도상환수수료율이 기존 1.2~1.4%에서 '0.55%~0.75%' 수준(신용대출은 0.1%대 이하!)으로 절반 이하로 뚝 떨어졌습니다!",
