     "1금융권 최저금리 대출을 받으려면 KCB(올크레딧)와 NICE(나이스) 신용평점 두 가지를 모두 관리해야 합니다. 가장 빠르고 돈 한 푼 안 드는 점수 상승 비법은 토스, 카카오페이, 네이버페이, 뱅크샐러드 앱에서 '신용점수 올리기(비금융정보 제출)' 버튼을 누르는 것입니다! 국민연금·건강보험료·통신비·아파트관리비 성실 납부 내역과 소득금액증명원이 신용평가사에 전송되어 그 자리에서 즉시 10점~50점이 오릅니다.",
