     "은행이나 카드사, 저축은행에서 대출을 받은 뒤 내 경제적 상태가 처음 대출받을 때보다 좋아졌다면, 만기 전이라도 언제든 금융회사에 '내 대출 금리를 깎아달라'고 법적으로 요구할 수 있는 권리가 바로 '금리인하요구권'입니다!",
