     "직장인 자녀의 건강보험에 '피부양자'로 올라가 있으면 매달 내는 건강보험료가 0원이지만, 자격 요건에서 단 하나라도 어긋나는 순간 지역가입자로 전환되어 매월 15만~35만 원(연 200만~400만 원)의 건보료 고지서가 날아옵니다!",
