    ("blog-sal-national-pension-early-vs-deferred-7-2-percent-2026", "salary", "급여·세무", "조기연금vs연기연금", "subsidy-national-pension-calc.html", "국민연금 수령액 계산기",
     "국민연금 5년 일찍 받으면 30% 깎이고, 5년 늦춰 받으면 36% 더 줍니다! 내 수명과 건보료까지 따진 조기노령연금 vs 연기연금 손익분기점",
     ["조기노령연금손익분기점", "연기연금36%증액", "국민연금수령나이"],
     "국민연금은 원래 정해진 수령 나이(1969년생 이후 기준 만 65세)보다 최대 5년 일찍 당겨 받는 '조기노령연금(만 60세~)'과, 반대로 최대 5년 늦춰 받는 '연기연금(~만 70세)' 중 본인이 직접 선택할 수 있습니다. 1년 일찍 받을 때마다 연금액이 연 6%(5년 최대 30%)씩 평생 깎이고, 1년 늦춰 받을 때마다 연 7.2%(5년 최대 36%!)씩 평생 늘어납니다.",
     "단순 금액만 보면 늦게 받는 연기연금이 유리해 보이지만, 숨겨진 변수가 바로 '건강보험 피부양자 기준(연 2,000만 원, 월 166.6만 원)'과 '기초연금 감액 기준'입니다! 만약 연기연금으로 월 수령액을 36% 늘렸다가 월 연금액이 167만 원을 넘어 건강보험 피부양자에서 탈락하면, 연금은 한 달에 30만 원 더 받고 건보료로 매달 25만 원을 토해내는 대참사가 벌어집니다. 따라서 예상 월 연금액이 130만~160만 원대라면 연기연금 대신 제때(정상 수령) 받거나 조기수령을 택해 피부양자 자격을 지키는 것이 훨씬 이득입니다!",
     "조기노령연금 (1~5년 조기 수령)", "1년당 -6% 감액 (5년 조기 시 70%만 평생 수령)", "은퇴 후 소득 공백기 해소 및 월 연금액 낮춰 피부양자 유지에 유리!",
     "정상 노령연금 (법정 개시 연령)", "100% 기본 연금액 평생 수령 (물가상승률 매년 반영)", "조기연금 대비 손익분기점은 약 만 76세 ~ 78세 전후",
     "연기연금 (1~5년 수령 유예)", "1년당 +7.2% 증액 (5년 연기 시 136% 평생 수령)", "주의: 증액 후 연 2,000만 원 초과 시 건보 피부양자 탈락 위험!",
     "정상 수령 시 예상 국민연금이 월 150만 원(연 1,800만 원)인 은퇴자 최 씨가 5년 연기연금을 고민한 사례",
     "연기 시 월 204만 원(연 2,448만 원)이 되어 건보 피부양자 탈락(연 280만 원 건보료 발생) 확인 &rarr; 연기하지 않고 정상 수령(월 150만)을 택해 피부양자 자격 유지 및 만 65세~70세 기간 동안 연금 9,000만 원 선수령!"),

