     "신용·체크카드 공제 (총급여 25% 문턱)", "연봉이 낮은 배우자 카드로 생활비 집중 결제!", "연봉 4천만(문턱 1,000만)이 연봉 8천만(문턱 2,000만)보다 공제 진입이 2배 빠름",
     "의료비 세액공제 (총급여 3% 문턱)", "연봉이 낮은 배우자에게 부부·자녀 병원비 전액 합산!", "의료비는 기본공제(인적공제)를 다른 배우자가 받은 부양가족 것도 합산 가능!",
