     ["프리랜서종합소득세환급", "단순경비율기준경비율차이", "3.3%원천징수환급"],
     "인적용역 프리랜서, 학원강사, 디자이너, 플랫폼 배달라이더, 크리에이터가 보수를 받을 때 먼저 떼이는 3.3% 세금은 확정된 세금이 아니라 국가가 일단 임시로 걷어간 '예납 세금'입니다! 매년 5월 홈택스 '모두채움 신고'를 통해 정산을 하면, 전년도 수입금액이 인적용역 기준 '2,400만 원 미만(당해 연도 신규 개업자는 7,500만 원 미만)'인 경우 영수증이 단 한 장 없어도 수입의 60%~79%를 자동으로 경비로 인정해 주는 '단순경비율'이 적용되어 떼인 3.3% 세금의 80~100%를 현금으로 돌려받습니다!",
     "반대로 수입금액이 2,400만 원을 넘어 '기준경비율' 대상자가 되었는데 아무 경비 증빙 없이 추계 신고를 하면 경비 인정률이 10~20%대로 급락해 오히려 세금을 더 토해내야 합니다. 따라서 연 수입이 2,400만 원을 넘는 프리랜서는 반드시 사업용 신용카드를 홈택스에 등록하고 통신비, 노트북·장비 구입비, 차량유지비, 건강보험료 납부액, 노란우산공제를 꼼꼼히 반영해 간편장부로 신고해야 세금을 아낄 수 있습니다.",
     "단순경비율 대상 (직전 수입 2,400만 미만)", "영수증 없이도 수입의 약 60% ~ 79% 경비 자동 인정!", "5월 홈택스 모두채움 원클릭 신고 시 떼인 3.3% 대부분 전액 환급",
