     "직장인이 퇴근 후나 주말에 3.3% 프리랜서 알바, 블로그·유튜브 애드센스, 쿠팡파트너스, 스마트스토어, 배달 등 '투잡(N잡)'을 할 때 가장 두려워하는 질문은 '회사 인사팀이나 사장님이 내 부업 사실을 알게 될까?'입니다. 결론부터 말씀드리면 국세청은 개인정보보호법상 근로자의 부업 소득이나 종합소득세 신고 사실을 회사에 절대 통보하지 않습니다!",
