     "같은 연봉 4,500만 원을 받아도 급여명세서 안에 '비과세 수당'이 얼마나 들어 있느냐에 따라 매달 통장에 찍히는 실수령액이 연간 100만 원 가까이 차이 납니다! 비과세 수당에는 소득세(6~45%)뿐만 아니라 국민연금(4.75%), 건강보험(3.595%), 고용보험(0.9%) 등 4대보험료까지 단 1원도 부과되지 않기 때문입니다.",
