     "상시근로자 5인 이상 사업장이라면 입사 1년 미만 신입사원은 1개월 개근 시마다 1개씩 최대 '11개', 만 1년 이상 근속한 근로자는 기본 '15개'(3년 이상부터 2년마다 1개씩 가산, 최대 25개)의 유급 연차휴가가 법적으로 발생합니다. 이 연차를 1년 동안 다 쓰지 못하면 남은 연차 일수만큼 '1일 통상임금 × 미사용 연차 일수'를 현금(연차미사용수당)으로 지급받아야 합니다!",
     "많은 회사가 '우리는 연차촉진제를 시행하니까 안 쓰면 돈 안 준다'고 주장하지만, 근로기준법 제61조가 정한 엄격한 서면 통보 절차(소멸 6개월 전 1차 서면 촉구 + 2개월 전 회사가 사용 시기 지정 통보)를 하나라도 어겼거나, 직원이 휴가 날에 출근해 일하는 것을 회사가 알면서도 명확히 노무 수령 거부를 하지 않았다면 연차촉진제는 무효가 되어 수당을 100% 다 줘야 합니다!",
     "입사 1년 미만 ~ 만 1년 시점 연차", "1개월 개근 시 1개(최대 11개) + 1년 만근 시 15개 = 총 26개", "단, 딱 365일만 채우고 퇴사 시 15개는 미발생 (366일 이상 재직 시 26개 전부 발생!)",
     "1일 연차수당 계산 공식", "(월 통상임금 ÷ 209시간) × 8시간", "월 통상임금 300만 원 기준 연차 1개당 약 114,830원 현금 정산!",
