def expand_gov_finder_to_100() -> int:
    gov_path = ROOT_DIR / "gov-finder.html"
    content = gov_path.read_text(encoding="utf-8")

    if "biz_one_person_social_ins" not in content:
        target_end = """                keywords: ['주거급여', '임차급여', '수선유지급여', '월세지원금', '저소득주거지원', '중위소득48%'],
                match: (u) => u.income === 'low' || u.income === 'under36'
            }
        ];"""
        replacement_end = f"""                keywords: ['주거급여', '임차급여', '수선유지급여', '월세지원금', '저소득주거지원', '중위소득48%'],
                match: (u) => u.income === 'low' || u.income === 'under36'
            }},
{ADDITIONAL_40_POLICIES_JS}
        ];"""
        if target_end not in content:
            raise RuntimeError("Could not locate POLICIES array end in gov-finder.html")
        content = content.replace(target_end, replacement_end, 1)

    # Update UI counts from 60 / 25 / 35 to 100 / 45 / 55
    replacements = [
        ("60개 핵심 지원금", "100개 핵심 지원금"),
        ("60대 정부지원금", "100대 정부지원금"),
        ("60건", "100건"),
        ("소상공인·사업자 25대 지원금", "소상공인·사업자 45대 지원금"),
        ("사업자 특화 25개 지원금 DB", "사업자 특화 45개 지원금 DB"),
        ("개인·가구 35대 지원금", "개인·가구 55대 지원금"),
        ("개인·가구 35개 지원금 DB", "개인·가구 55개 지원금 DB"),
        ('id="categoryTabBusiness"\n                        class="flex-1 py-2.5 px-3 rounded-xl bg-slate-50 text-slate-700 hover:bg-slate-100 transition flex items-center justify-center gap-1.5 border border-slate-200/80">\n                        <span>소상공인·사업자 지원금</span>\n                        <span class="px-1.5 py-0.5 rounded-md bg-blue-100 text-blue-700 text-[10px] font-extrabold">25건</span>',
         'id="categoryTabBusiness"\n                        class="flex-1 py-2.5 px-3 rounded-xl bg-slate-50 text-slate-700 hover:bg-slate-100 transition flex items-center justify-center gap-1.5 border border-slate-200/80">\n                        <span>소상공인·사업자 지원금</span>\n                        <span class="px-1.5 py-0.5 rounded-md bg-blue-100 text-blue-700 text-[10px] font-extrabold">45건</span>'),
        ('id="categoryTabPersonal"\n                        class="flex-1 py-2.5 px-3 rounded-xl bg-slate-50 text-slate-700 hover:bg-slate-100 transition flex items-center justify-center gap-1.5 border border-slate-200/80">\n                        <span>개인·가구 복지</span>\n                        <span class="px-1.5 py-0.5 rounded-md bg-slate-200/80 text-slate-700 text-[10px] font-extrabold">35건</span>',
         'id="categoryTabPersonal"\n                        class="flex-1 py-2.5 px-3 rounded-xl bg-slate-50 text-slate-700 hover:bg-slate-100 transition flex items-center justify-center gap-1.5 border border-slate-200/80">\n                        <span>개인·가구 복지</span>\n                        <span class="px-1.5 py-0.5 rounded-md bg-slate-200/80 text-slate-700 text-[10px] font-extrabold">55건</span>'),
    ]
    for old_s, new_s in replacements:
        content = content.replace(old_s, new_s)

    gov_path.write_text(content, encoding="utf-8")
    total_ids = len(re.findall(r"\bid:\s*'", content))
    print(f"[gov-finder.html] Expanded POLICIES DB to {total_ids} subsidies (45 Business + 55 Personal).")
    return total_ids


def build_all_new_topics() -> list[dict]:
    topics: list[dict] = []
    seen_slugs: set[str] = set()

    # 1. Include any unpublished topics from TOPIC_CATALOG
    for t in TOPIC_CATALOG:
        slug = t["slug"]
        if not (ROOT_DIR / f"{slug}.html").exists() and slug not in seen_slugs:
            topics.append(t)
            seen_slugs.add(slug)

    # 2. Include all RAW_SPECS
    for rs in RAW_SPECS:
        t = raw_spec_to_topic(rs)
        slug = t["slug"]
        if slug not in seen_slugs and not (ROOT_DIR / f"{slug}.html").exists():
            topics.append(t)
            seen_slugs.add(slug)

    # 3. Include all PARAMETRIC_75
    for pm in PARAMETRIC_75:
        t = parametric_to_topic(pm)
        slug = t["slug"]
        if slug not in seen_slugs and not (ROOT_DIR / f"{slug}.html").exists():
            topics.append(t)
            seen_slugs.add(slug)

    return topics


